set-variable.value:
@{
        try {
          var b = context.Request.Body.As<JObject>(preserveContent: true);
          var s = b["stream"];
          return (s != null && s.Type == JTokenType.Boolean && (bool)s) ? "true" : "false";
        } catch (Exception) { return "false"; }
        }

@{
        Func<JToken, string> text = c => {
          if (c == null) return "";
          if (c.Type == JTokenType.String) return (string)c;
          var sb = new System.Text.StringBuilder();
          var arr = c as JArray;
          if (arr != null) { foreach (var p in arr) { var t = p["text"]; if (t != null && t.Type == JTokenType.String) { sb.Append((string)t).Append("\n"); } } }
          return sb.ToString();
        };

        try {
          var b = context.Request.Body.As<JObject>(preserveContent: true);
          var msgs = b["messages"] as JArray;
          if (msgs == null) return "";
          var user = new System.Text.StringBuilder();
          var docs = new JArray();
          foreach (var m in msgs) {
            string role = (string)m["role"]; string t = text(m["content"]);
            if (t.Length == 0) continue;
            if (role == "user") { user.Append(t).Append("\n"); }
            else if (role == "tool" && docs.Count < 5) { docs.Add(t.Length > 10000 ? t.Substring(0, 10000) : t); }
          }
          string u = user.ToString();
          if (u.Length == 0) return "";
          if (u.Length > 10000) { u = u.Substring(u.Length - 10000); }
          return new JObject(new JProperty("userPrompt", u), new JProperty("documents", docs)).ToString(Newtonsoft.Json.Formatting.None);
        } catch (Exception) { return ""; }
        }

@{
        Func<JToken, string> text = c => {
          if (c == null) return "";
          if (c.Type == JTokenType.String) return (string)c;
          var sb = new System.Text.StringBuilder();
          var arr = c as JArray;
          if (arr != null) { foreach (var p in arr) { var t = p["text"]; if (t != null && t.Type == JTokenType.String) { sb.Append((string)t).Append("\n"); } } }
          return sb.ToString();
        };

        try {
          var b = context.Request.Body.As<JObject>(preserveContent: true);
          var msgs = b["messages"] as JArray;
          if (msgs == null) return "";
          var sb = new System.Text.StringBuilder();
          foreach (var m in msgs) { if ((string)m["role"] == "user") { sb.Append(text(m["content"])).Append("\n"); } }
          string u = sb.ToString();
          if (u.Trim().Length == 0) return "";
          if (u.Length > 10000) { u = u.Substring(u.Length - 10000); }
          return new JObject(new JProperty("text", u), new JProperty("categories", new JArray("Hate", "SelfHarm", "Sexual", "Violence")), new JProperty("outputType", "FourSeverityLevels")).ToString(Newtonsoft.Json.Formatting.None);
        } catch (Exception) { return ""; }
        }

@{
                try {
                  var r = (IResponse)context.Variables["rp-shield-resp"];
                  if (r == null) return "dependency";
                  int s = r.StatusCode;
                  if (s == 200) {
                    var j = r.Body.As<JObject>();
                    bool a = false;
                    var u = j.SelectToken("userPromptAnalysis.attackDetected");
                    if (u != null && u.Type == JTokenType.Boolean && (bool)u) { a = true; }
                    var docs = j["documentsAnalysis"] as JArray;
                    if (docs != null) { foreach (var d in docs) { var x = d["attackDetected"]; if (x != null && x.Type == JTokenType.Boolean && (bool)x) { a = true; } } }
                    return a ? "attack" : "clean";
                  }
                  if (s == 401 || s == 403) return "auth";
                  if (s == 408 || s == 429 || s >= 500) return "dependency";
                  return "config";
                } catch (Exception) { return "dependency"; }
                }

@{
                try {
                  var r = (IResponse)context.Variables["rp-analyze-resp"];
                  if (r == null) return "dependency";
                  int s = r.StatusCode;
                  if (s == 200) {
                    var j = r.Body.As<JObject>();
                    var allowed = new string[] { "Hate", "SelfHarm", "Sexual", "Violence" };
                    string cat = ""; int sev = 0;
                    var items = j["categoriesAnalysis"] as JArray;
                    if (items != null) {
                      foreach (var i in items) {
                        string c = (string)i["category"]; var sv = i["severity"];
                        if (c != null && Array.IndexOf(allowed, c) >= 0 && sv != null && sv.Type == JTokenType.Integer && (int)sv > sev) { cat = c; sev = (int)sv; }
                      }
                    }
                    return "ok:" + cat + ":" + sev.ToString();
                  }
                  if (s == 401 || s == 403) return "auth";
                  if (s == 408 || s == 429 || s >= 500) return "dependency";
                  return "config";
                } catch (Exception) { return "dependency"; }
                }

@{
                string s = (string)context.Variables["rp-shield-result"];
                string a = (string)context.Variables["rp-analyze-result"];
                bool over = a.StartsWith("ok:") && int.Parse(a.Split(':')[2]) >= {severity-threshold};
                if (s == "attack" || over) return "block";
                if (!context.Variables.ContainsKey("rp-cs-token") || s == "auth" || s == "config" || a == "auth" || a == "config") return "error";
                if (s == "dependency" || a == "dependency") {
                  return ((string)context.Variables["rp-safety-mode"]) == "regulated" ? "error" : "allowed_on_safety_error";
                }
                return "allow";
                }
